package proxy

import "encoding/json"

func dashboardHTML(localAPIKey string) string {
	key, _ := json.Marshal(localAPIKey)
	return `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KimiSwitch</title>
<style>
:root{color-scheme:dark;--bg:#090e1b;--panel:#111a2e;--border:#263756;--text:#edf3ff;--muted:#91a0bd;--blue:#6ea8fe;--green:#55d68b;--yellow:#ffc857;--red:#ff7586}*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","Segoe UI",sans-serif;color:var(--text);background:radial-gradient(circle at 85% 0,#203967 0,#090e1b 42%)}button,input,select,textarea{font:inherit}main{max-width:1120px;margin:auto;padding:34px 24px 64px}header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:24px}h1{margin:0;font-size:32px;letter-spacing:-.04em}.subtitle{margin-top:7px;color:var(--muted);font-size:14px}.header-actions,.toolbar,.actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap}button{border:1px solid #38517d;border-radius:10px;color:var(--text);background:#1a2947;padding:9px 13px;cursor:pointer}button:hover{background:#263d68}button.primary{background:#3568b8;border-color:#6ea8fe}button.ghost{background:transparent;border-color:#31415f}button.danger:hover{color:#fff;border-color:#b64d5c;background:#74323c}button:disabled{opacity:.5;cursor:default}.overview{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:18px}.panel,.metric,.provider{border:1px solid var(--border);background:rgba(17,26,46,.88);box-shadow:0 16px 42px rgba(0,0,0,.16)}.metric{border-radius:16px;padding:17px}.metric-label{color:var(--muted);font-size:11px;letter-spacing:.09em;text-transform:uppercase}.metric-value{margin-top:9px;font-size:19px;font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.panel{border-radius:18px;padding:18px}.toolbar{margin-bottom:14px}.search{flex:1;min-width:220px;border:1px solid #324665;background:#0d1628;color:var(--text);border-radius:10px;padding:10px 12px;outline:none}.search:focus,input:focus,select:focus,textarea:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(110,168,254,.14)}.provider-list{display:grid;gap:12px}.provider{border-radius:15px;padding:16px;display:grid;grid-template-columns:minmax(200px,1.4fr) minmax(220px,1fr) auto;gap:18px;align-items:center}.provider.active{border-color:#4f79b9;background:linear-gradient(100deg,rgba(30,53,91,.96),rgba(17,26,46,.9))}.provider.disabled{opacity:.62}.provider-title{display:flex;align-items:center;gap:9px;font-weight:680;font-size:16px}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 10px currentColor;color:var(--green)}.dot.cooldown{background:var(--yellow);color:var(--yellow)}.dot.error,.dot.disabled{background:var(--red);color:var(--red)}.provider-meta,.provider-note{color:var(--muted);font-size:12px;margin-top:5px}.provider-note{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em}.stat strong{display:block;margin-top:5px;font-size:14px;font-variant-numeric:tabular-nums}.actions{justify-content:flex-end}.actions button{padding:7px 10px;font-size:12px}.empty{text-align:center;padding:52px 20px;border:1px dashed #344765;border-radius:15px;color:var(--muted)}.empty h3{color:var(--text);margin:0 0 8px}.empty .actions{justify-content:center;margin-top:20px}.notice{position:fixed;right:20px;bottom:20px;max-width:420px;border:1px solid #3b5680;background:#162747;padding:12px 15px;border-radius:12px;opacity:0;transform:translateY(10px);pointer-events:none;transition:.18s}.notice.show{opacity:1;transform:none}.notice.error{border-color:#a74957;background:#512630}dialog{width:min(560px,calc(100vw - 28px));color:var(--text);background:#111a2e;border:1px solid #344867;border-radius:18px;padding:0;box-shadow:0 30px 90px rgba(0,0,0,.5)}dialog::backdrop{background:rgba(2,6,14,.72);backdrop-filter:blur(6px)}.dialog-head{padding:18px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center}.dialog-head h2{margin:0;font-size:18px}.dialog-body{padding:20px;display:grid;gap:15px}.field{display:grid;gap:6px}.field label{color:#b8c4da;font-size:12px}.field input,.field select,.field textarea{width:100%;border:1px solid #324665;background:#0c1527;color:var(--text);border-radius:9px;padding:10px 11px;outline:none}.field textarea{min-height:74px;resize:vertical}.field-hint{color:var(--muted);font-size:11px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.check{display:flex;align-items:center;gap:8px;color:#c7d2e7;font-size:13px}.dialog-foot{display:flex;justify-content:flex-end;gap:9px;padding:15px 20px;border-top:1px solid var(--border)}@media(max-width:820px){main{padding:24px 14px 44px}header{display:block}.header-actions{margin-top:16px}.overview{grid-template-columns:repeat(2,minmax(0,1fr))}.provider{grid-template-columns:1fr}.actions{justify-content:flex-start}.row{grid-template-columns:1fr}}
</style></head><body><main>
<header><div><h1>KimiSwitch</h1><div class="subtitle">参考 CC Switch 的账号管理 · Kimi 专用本地代理</div></div><div class="header-actions"><button id="importButton" class="ghost">导入当前配置</button><button id="settingsButton" class="ghost">设置</button><button id="createButton" class="primary">＋ 新建账号</button></div></header>
<section class="overview"><div class="metric"><div class="metric-label">Rotation</div><div id="rotation" class="metric-value">—</div></div><div class="metric"><div class="metric-label">Mode</div><div id="mode" class="metric-value">—</div></div><div class="metric"><div class="metric-label">Active</div><div id="active" class="metric-value">—</div></div><div class="metric"><div class="metric-label">Accounts</div><div id="accountCount" class="metric-value">—</div></div></section>
<section class="panel"><div class="toolbar"><input id="search" class="search" placeholder="搜索账号、备注…"><button id="toggleRotation">切换轮换</button></div><div id="keyList" class="provider-list"><div class="empty">正在读取配置…</div></div></section>
</main>
<dialog id="keyDialog"><form id="keyForm"><div class="dialog-head"><h2 id="keyDialogTitle">新建账号</h2><button type="button" class="ghost" data-close="keyDialog">关闭</button></div><div class="dialog-body"><input id="originalName" type="hidden"><div class="row"><div class="field"><label for="keyName">名称</label><input id="keyName" required placeholder="work / personal"></div><div class="field"><label for="keyAccount">账号标识</label><input id="keyAccount" placeholder="邮箱或用途，可选"></div></div><div class="field"><label for="keyNotes">备注</label><textarea id="keyNotes" placeholder="套餐、归属、用途等"></textarea></div><div class="field"><label for="apiKey">Kimi Code API Key</label><input id="apiKey" type="password" autocomplete="off" placeholder="编辑时留空表示保持原 Key"><div class="field-hint">输入后保存到系统凭据库，不写入配置文件。</div></div><div class="field"><label for="apiKeyEnv">或者使用环境变量</label><input id="apiKeyEnv" placeholder="例如 KIMI_WORK_KEY"><div class="field-hint">API Key 与环境变量二选一；API Key 优先保存到系统凭据库。</div></div><label class="check"><input id="keyEnabled" type="checkbox" checked>参与代理与轮换</label></div><div class="dialog-foot"><button type="button" class="ghost" data-close="keyDialog">取消</button><button type="submit" class="primary">保存账号</button></div></form></dialog>
<dialog id="settingsDialog"><form id="settingsForm"><div class="dialog-head"><h2>代理与轮换设置</h2><button type="button" class="ghost" data-close="settingsDialog">关闭</button></div><div class="dialog-body"><div class="field"><label for="upstream">Kimi 上游地址</label><input id="upstream" required></div><div class="row"><div class="field"><label for="rotationMode">切换策略</label><input id="rotationMode" value="故障时切换" disabled></div><div class="field"><label for="maxAttempts">最大尝试账号数</label><input id="maxAttempts" type="number" min="1" max="20"></div></div><div class="field"><label for="cooldownSeconds">失败冷却（秒）</label><input id="cooldownSeconds" type="number" min="600"></div><label class="check"><input id="rotationEnabled" type="checkbox">开启自动轮换</label><label class="check"><input id="retryRateLimited" type="checkbox">遇到 429 时尝试下一个账号</label></div><div class="dialog-foot"><button type="button" class="ghost" data-close="settingsDialog">取消</button><button type="submit" class="primary">保存设置</button></div></form></dialog>
<div id="notice" class="notice"></div>
<script>
const localKey=` + string(key) + `;const headers={Authorization:'Bearer '+localKey,'Content-Type':'application/json'};const $=(id)=>document.getElementById(id);let current=null;let noticeTimer=null;const number=(value)=>Number(value||0).toLocaleString('zh-CN');const escapeHTML=(value)=>String(value==null?'':value).replace(/[&<>'"]/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
async function api(path,options){const response=await fetch(path,Object.assign({headers},options||{}));const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||('请求失败：'+response.status));return data}
function notify(message,error){const el=$('notice');el.textContent=message;el.className='notice show'+(error?' error':'');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.className='notice',3200)}
function stateFor(key,stats){if(!key.enabled)return['disabled','已停用'];const until=Date.parse(stats.cooldown_until||'');if(Number.isFinite(until)&&until>Date.now())return['cooldown','冷却中'];if(stats.last_error)return['error','最近失败'];return['','可用']}
function render(data){current=data;const c=data.config;$('rotation').textContent=c.rotation.enabled?'已开启':'已关闭';$('mode').textContent='故障时切换';$('active').textContent=c.active_key||'未选择';$('accountCount').textContent=c.keys.length+' 个';$('toggleRotation').textContent=c.rotation.enabled?'关闭轮换':'开启轮换';const keyword=$('search').value.trim().toLowerCase();const keys=c.keys.filter((k)=>!keyword||[k.name,k.account,k.notes].some((v)=>String(v||'').toLowerCase().includes(keyword)));if(!c.keys.length){$('keyList').innerHTML='<div class="empty"><h3>还没有账号</h3><div>可以导入 Kimi 当前配置，也可以手动新建。</div><div class="actions"><button data-empty="import" class="primary">导入当前配置</button><button data-empty="create">新建账号</button></div></div>';return}$('keyList').innerHTML=keys.map((key)=>{const stats=data.keys[key.name]||{};const state=stateFor(key,stats);const active=key.name===c.active_key;const sourceLabel=key.source==='keychain+local'?'Keychain + Local fallback':key.source==='keychain'?'Keychain':key.source==='environment'?key.api_key_env:'本地配置';return '<article class="provider '+(active?'active ':'')+(!key.enabled?'disabled':'')+'"><div><div class="provider-title"><span class="dot '+state[0]+'"></span>'+escapeHTML(key.name)+(active?' <span style="color:#7fb4ff;font-size:12px">当前</span>':'')+'</div><div class="provider-meta">'+escapeHTML(key.account||'未填写账号')+' · '+escapeHTML(sourceLabel)+'</div><div class="provider-note">'+escapeHTML(key.notes||state[1])+'</div></div><div class="stats"><div class="stat"><span>请求</span><strong>'+number(stats.requests)+'</strong></div><div class="stat"><span>真实 token</span><strong>'+number(stats.total_tokens)+'</strong></div><div class="stat"><span>失败</span><strong>'+number(stats.failures)+'</strong></div></div><div class="actions"><button data-action="use" data-name="'+escapeHTML(key.name)+'" '+(active?'disabled':'')+'>'+(active?'使用中':'设为当前')</button><button data-action="edit" data-name="'+escapeHTML(key.name)+'">编辑</button><button data-action="duplicate" data-name="'+escapeHTML(key.name)+'">复制</button><button data-action="toggle" data-name="'+escapeHTML(key.name)+'" data-enabled="'+key.enabled+'">'+(key.enabled?'停用':'重新启用')+'</button><button class="danger" data-action="delete" data-name="'+escapeHTML(key.name)+'">删除</button></div></article>'}).join('')||'<div class="empty">没有匹配的账号</div>'}
async function refresh(){try{render(await api('/api/status'))}catch(error){notify(error.message,true)}}
function openKeyDialog(name){const key=name&&current?current.config.keys.find((item)=>item.name===name):null;$('keyDialogTitle').textContent=key?'编辑账号':'新建账号';$('originalName').value=key?key.name:'';$('keyName').value=key?key.name:'';$('keyAccount').value=key?key.account||'':'';$('keyNotes').value=key?key.notes||'':'';$('apiKey').value='';$('apiKeyEnv').value=key?key.api_key_env||'':'';$('keyEnabled').checked=key?key.enabled:true;$('keyDialog').showModal()}
function openSettings(){const c=current.config;$('upstream').value=c.upstream_base_url;$('rotationMode').value='故障时切换';$('maxAttempts').value=c.rotation.max_attempts;$('cooldownSeconds').value=c.rotation.cooldown_seconds;$('rotationEnabled').checked=c.rotation.enabled;$('retryRateLimited').checked=c.rotation.retry_rate_limited;$('settingsDialog').showModal()}
async function importCurrent(){try{const result=await api('/api/import/kimi',{method:'POST',body:'{}'});notify('已导入：'+(result.imported.join('、')||'没有发现新账号'));await refresh()}catch(error){notify(error.message,true)}}
$('createButton').addEventListener('click',()=>openKeyDialog());$('importButton').addEventListener('click',importCurrent);$('settingsButton').addEventListener('click',openSettings);$('search').addEventListener('input',()=>current&&render(current));$('toggleRotation').addEventListener('click',async()=>{await api('/api/rotation',{method:'POST',body:JSON.stringify({enabled:!current.config.rotation.enabled,mode:'sticky'})});await refresh()});document.querySelectorAll('[data-close]').forEach((button)=>button.addEventListener('click',()=>$(button.dataset.close).close()));
$('keyList').addEventListener('click',async(event)=>{const empty=event.target.closest('[data-empty]');if(empty){empty.dataset.empty==='import'?importCurrent():openKeyDialog();return}const button=event.target.closest('[data-action]');if(!button)return;const name=button.dataset.name;const action=button.dataset.action;try{if(action==='edit'){openKeyDialog(name);return}if(action==='delete'&&!confirm('删除账号“'+name+'”？系统凭据库中的原始 Key 不会被删除。'))return;if(action==='use')await api('/api/keys/'+encodeURIComponent(name)+'/use',{method:'POST'});if(action==='duplicate')await api('/api/keys/'+encodeURIComponent(name)+'/duplicate',{method:'POST'});if(action==='toggle')await api('/api/keys/'+encodeURIComponent(name)+'/toggle',{method:'POST',body:JSON.stringify({enabled:button.dataset.enabled!=='true'})});if(action==='delete')await api('/api/keys/'+encodeURIComponent(name),{method:'DELETE'});notify(action==='delete'?'账号已删除':'操作已完成');await refresh()}catch(error){notify(error.message,true)}});
$('keyForm').addEventListener('submit',async(event)=>{event.preventDefault();const original=$('originalName').value;const payload={name:$('keyName').value,account:$('keyAccount').value,notes:$('keyNotes').value,api_key:$('apiKey').value,api_key_env:$('apiKeyEnv').value,enabled:$('keyEnabled').checked};try{await api(original?'/api/keys/'+encodeURIComponent(original):'/api/keys',{method:original?'PUT':'POST',body:JSON.stringify(payload)});$('keyDialog').close();notify(original?'账号已更新':'账号已创建');await refresh()}catch(error){notify(error.message,true)}});
$('settingsForm').addEventListener('submit',async(event)=>{event.preventDefault();const payload={upstream_base_url:$('upstream').value,rotation:{enabled:$('rotationEnabled').checked,mode:'sticky',max_attempts:Number($('maxAttempts').value),cooldown_seconds:Number($('cooldownSeconds').value),retry_rate_limited:$('retryRateLimited').checked}};try{await api('/api/settings',{method:'PUT',body:JSON.stringify(payload)});$('settingsDialog').close();notify('设置已保存');await refresh()}catch(error){notify(error.message,true)}});refresh();setInterval(refresh,5000);
</script></body></html>`
}
